<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withName,
 * getName/name accessors, and isNameChanged with/without original.
 */
class UserWebauthnCredentialNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withName creates a new instance with the Name set
     * from a string value, and getName returns the primitive string.
     */
    public function testWithNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialNameAccessorUnitTest();

        // Act
        $result = $holder->withName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getName());
    }
    /**
     * Asserts that withname has access to the value object
     * from a string value, and getName returns the primitive string.
     */
    public function testWithNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialNameAccessorUnitTest();

        // Act
        $result = $holder->withName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->name()->value());
    }
    public function testChangedName(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialNameAccessorUnitTest()->withName('one');
        $original = $holder->withName('one');
        $same = $holder->withName('one');
        $modified = $holder->withName('other');

        // Act
        $withSame = $original->isNameChanged($same);
        $withDiferent = $original->isNameChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialNameAccessorUnitTest
{
    use UserWebauthnCredentialNameAccessor;
}
